const paths={spark:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7L12 3Z',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',calendar:'M5 5h14a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7a2 2 0 0 1 2-2Z M16 3v4 M8 3v4 M3 11h18 M8 15h2 M14 15h2',bag:'M5 7h14l2 14H3L5 7Z M8 8V6a4 4 0 0 1 8 0v2',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z',user:'M20 21v-2a7 7 0 0 0-14 0v2 M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 6v6l4 2',flame:'M12 3c1 5 6 6 6 12a6 6 0 0 1-12 0c0-3 2-5 3-6 0 3 2 4 2 4s3-4 1-10Z',leaf:'M20 3c1 11-2 17-10 17a7 7 0 0 1-7-7C3 5 11 3 20 3Z M3 21 16 8',arrow:'M4 12h16 M14 6l6 6-6 6',chevron:'m9 5 7 7-7 7',plus:'M12 5v14 M5 12h14',minus:'M5 12h14',x:'m6 6 12 12 M6 18 18 6',check:'m5 12 4 4L19 6',undo:'M3 10h11a6 6 0 0 1 0 12 M3 10l5-5 M3 10l5 5',sliders:'M4 7h5 M13 7h7 M4 17h9 M17 17h3 M9 4v6 M13 14v6',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0 M15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',info:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0 M12 11v6 M12 7v1',search:'M21 21l-6-6 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',edit:'m15 4 5 5 M4 20l4-1L20 7a2 2 0 0 0-4-4L4 15v5Z',trash:'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',fork:'M4 3v5a3 3 0 0 0 6 0V3 M7 3v18 M18 3c-3 3-4 8 0 9v9 M18 3v9',home:'m3 10 9-7 9 7 M5 9v12h5v-7h4v7h5V9',bolt:'m13 2-9 12h7l-1 8 10-12h-7l1-8',shuffle:'m3 4 18 16 M16 20h5v-5 M3 20l7-7 M14 9l7-5 M16 4h5v5',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',book:'M12 5c-3-2-6-2-10-1v16c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Z M12 5v16',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M12 1v2 M12 21v2 M1 12h2 M21 12h2 M4 4l2 2 M18 18l2 2 M4 20l2-2 M18 6l2-2'};
function icon(name){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;}
let storageAvailable=true,storageRecovered=false,state=defaults(),savedState=null;
try{savedState=localStorage.getItem(STORE_KEY);}catch{storageAvailable=false;}
if(savedState!==null){try{state=sanitize(JSON.parse(savedState));}catch{storageRecovered=true;}}
let ui={view:location.hash.slice(1)||'home',shop:{category:'all',search:'',sort:'recommended',favorites:false,personal:false},shopLimit:30,recipeFavorites:false,banner:0,bannerPaused:!!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches,category:'all',quick:false,cheap:false,search:'',limit:24,day:0,modal:null,lastSkip:null,toastAction:null,seed:new Date().toLocaleDateString('en-CA'),previousFocus:null};
if(ui.view==='favorites'){ui.view='catalog';ui.recipeFavorites=true;}
if(!['home','feed','catalog','menu','cart','profile','integration'].includes(ui.view))ui.view='home';
let toastTimer;
function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));storageAvailable=true;}catch{if(storageAvailable)toast('Хранилище недоступно. Изменения сохранятся только до закрытия страницы.');storageAvailable=false;}}
function image(r,cls='',lazy=true){return `<img decoding="async" ${lazy?'loading="lazy"':''} src="${esc(recipePhoto(r))}" alt="Иллюстрация подачи: ${esc(r.title)}" class="${cls}" draggable="false">`;}
function photoCredit(r){const c=recipePhotoCredit(r);if(!c)return '';return `<details class="photo-credit"><summary>Автор фотографии и лицензия</summary><p>Фото: <a href="${esc(c.sourceUrl)}" target="_blank" rel="noopener">${esc(c.author)}</a> · ${esc(c.source)} · <a href="${esc(c.licenseUrl)}" target="_blank" rel="noopener">${esc(c.license)}</a>${c.attribution?`<br>${esc(c.attribution)}`:''}${c.modifications?`<br>${esc(c.modifications)}`:''}</p></details>`;}
function dayName(n){if(n===0)return 'Сегодня';if(n===1)return 'Завтра';return new Date(Date.now()+n*86400000).toLocaleDateString('ru-RU',{weekday:'short',day:'numeric'});}
function selected(id){return state.selected.find(x=>x.id===id);}
function fullBasket(){return basket(state);}
function total(){return fullBasket().reduce((n,i)=>n+i.total,0);}
function toast(text,action,label='Отменить'){clearTimeout(toastTimer);ui.toastAction=action||null;$('#toast').innerHTML=`<span>${esc(text)}</span>${action?`<button data-action="toast-action">${label}</button>`:''}`;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),6000);}
function go(view,{replace=false}={}){if(view==='favorites'){view='catalog';ui.recipeFavorites=true;}else if(view==='catalog')ui.recipeFavorites=false;ui.view=view;ui.limit=24;ui.search='';closeModal(false);if(location.hash!=='#'+view)history[replace?'replaceState':'pushState'](null,'','#'+view);render();window.scrollTo({top:0,behavior:'instant'});}
const nav=[['home','home','Главная'],['catalog','book','Рецепты'],['feed','spark','Для вас'],['cart','bag','Корзина'],['profile','user','Профиль']];
function render(){
 stopCarousel();
 document.documentElement.dataset.store=state.store;
 document.title=(state.store==='fresh'?'FreshMarket':'Авоська')+(ui.view==='home'?' · Продукты и рецепты':' · Что приготовим?');
 document.querySelector('meta[name="theme-color"]').content=state.store==='fresh'?'#93c12d':'#f8dc33';
 document.querySelector('link[rel="icon"]').href=state.store==='fresh'?'assets/freshmarket-logo.svg':'assets/avoska-logo.png';
 const brandName=state.store==='fresh'?'FreshMarket':'Авоська';
 const brandLogo=state.store==='fresh'?'assets/freshmarket-logo.svg':'assets/avoska-logo.png';
 const items=fullBasket().filter(i=>!i.atHome).length;
 $('#app').innerHTML=`<aside class="sidebar"><button class="brand official-brand" data-action="nav" data-view="home" aria-label="${brandName}, главная"><img src="${brandLogo}" alt="${brandName}" class="official-logo"></button><div class="brand-caption">${state.store==='fresh'?'ПОКУПАЙ СО ВКУСОМ':'ВАШ НАДЁЖНЫЙ СОСЕД'}</div><nav class="sidebar-nav">${nav.map(([id,ic,title])=>`<button class="nav-item ${(ui.view===id||(id==='catalog'&&ui.view==='menu')||(id==='profile'&&ui.view==='integration'))?'active':''}" data-action="nav" data-view="${id}" ${(ui.view===id||(id==='catalog'&&ui.view==='menu')||(id==='profile'&&ui.view==='integration'))?'aria-current="page"':''}>${icon(ic)}<span>${title}</span>${id==='cart'&&items?`<span class="count">${items}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="taste-note">${icon('leaf')}<h3>${state.store==='fresh'?'Маленький выбор.<br>Большая забота о себе.':'Вкусно по-домашнему.<br>Выгодно каждый день.'}</h3><p>Готовьте то, что нравится.<br>Остальное мы соберём.</p></div><div class="store-switch"><button class="${state.store==='fresh'?'active':''}" data-action="store" data-store="fresh">FreshMarket</button><button class="avoska ${state.store==='avoska'?'active':''}" data-action="store" data-store="avoska">Авоська</button></div><div class="beta-note"><span class="dot"></span>Демонстрационная версия</div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">${icon('home')}<span>/</span><strong>${ui.view==='menu'?'Рецепты / Моё меню':ui.view==='integration'?'Профиль / Интеграция':nav.find(x=>x[0]===ui.view)?.[2]||'Профиль'}</strong></div><button class="mobile-logo official-brand" data-action="switch-store" aria-label="${brandName}. Переключить магазин"><img class="official-logo" src="${brandLogo}" alt="${brandName}"><span class="muted">⌄</span></button><div class="top-right"><div class="header-stores" aria-label="Выбор магазина"><button data-action="store" data-store="fresh" class="${state.store==='fresh'?'active':''}" aria-pressed="${state.store==='fresh'}">FreshMarket</button><button data-action="store" data-store="avoska" class="${state.store==='avoska'?'active':''}" aria-pressed="${state.store==='avoska'}">Авоська</button></div><span class="row location">${icon('pin')}Благовещенск</span><button class="badge" data-action="about">БЕТА · ДЕМОЦЕНЫ</button><button class="avatar" data-action="nav" data-view="profile" aria-label="Мой профиль">${icon('user')}</button></div></header>${({home:homePage,feed:feedPage,catalog:catalogPage,menu:menuPage,cart:cartPage,profile:profilePage,integration:integrationPage}[ui.view])()}<footer class="page-footer"><span>${brandName} · ${state.store==='fresh'?'Покупай со вкусом':'Ваш надёжный сосед'}</span><button data-action="about">О бете и данных ${icon('info')}</button></footer></main><nav class="mobile-nav">${nav.map(([id,ic,title])=>`<button data-action="nav" data-view="${id}" class="${(ui.view===id||(id==='catalog'&&ui.view==='menu')||(id==='profile'&&ui.view==='integration'))?'active':''}" ${(ui.view===id||(id==='catalog'&&ui.view==='menu')||(id==='profile'&&ui.view==='integration'))?'aria-current="page"':''}>${icon(ic)}<span>${title==='Моё меню'?'Меню':title}</span>${id==='cart'&&items?`<b class="count">${items}</b>`:''}</button>`).join('')}</nav>`;
 attachSwipe();attachCarousel();startCarousel();
}
function title(eyebrow,headline,sub,extra=''){return `<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${headline}</h1><p>${sub}</p></div>${extra}</div>`;}
function filters(){return `<div class="filterbar">${[['all','Всё'],['breakfast','Завтраки'],['lunch','Обеды'],['dinner','Ужины'],['salad','Салаты']].map(([id,label])=>`<button data-action="category" data-category="${id}" class="chip ${ui.category===id?'active':''}">${label}</button>`).join('')}<span class="filter-separator"></span><button data-action="quick" class="chip ${ui.quick?'active':''}">${icon('bolt')}До 20 мин</button><button data-action="cheap" class="chip ${ui.cheap?'active':''}">До 150 ₽</button><button data-action="nav" data-view="profile" class="text-button filter-button">${icon('sliders')}Мой вкус</button></div>`;}
function feedList(){let list=recommendations(state,{...ui,seed:ui.seed}).filter(r=>!state.favorites.includes(r.id));const first=RECIPES[0];if(!state.profile.configured&&ui.category==='all'&&!ui.quick&&!ui.cheap&&!state.skipped.length&&!state.disliked.includes(first.id)&&!state.favorites.includes(first.id)&&!selected(first.id)&&eligible(first,state.profile)){list=[first,...list.filter(x=>x.id!==first.id)];}return list;}
function feedPage(){const list=feedList(),r=list[0];const suggested=recommendations(state,{seed:ui.seed,excludeSelected:false,excludeSkipped:false}).filter(x=>x.id!==r?.id);const families=new Set();const cards=suggested.filter(x=>{if(families.has(x.family))return false;families.add(x.family);return true;}).slice(0,4);
 return `${title(state.store==='fresh'?'ХОРОШИЙ ДЕНЬ НАЧИНАЕТСЯ СО ВКУСА':'ВКУСНЫЕ ИДЕИ ДЛЯ ВСЕЙ СЕМЬИ','Что приготовим сегодня?','Листайте блюда и сохраняйте любимое. Решили готовить? Добавьте продукты в корзину.',`<div class="date-pill">${icon('sun')}${new Date().toLocaleDateString('ru-RU',{day:'numeric',month:'long',weekday:'short'})}</div>`)}${filters()}<div class="feature-layout"><div class="feed-block">${r?`<article class="swipe-card" id="swipe-card" tabindex="0" role="button" aria-label="${esc(r.title)}. Открыть рецепт" data-action="choose" data-id="${r.id}">${image(r,'',false)}<div class="swipe-top"><span class="pill">${icon('spark')}${esc(recommendationReason(r,state))}</span><button class="icon-button ${state.favorites.includes(r.id)?'saved fav-filled':''}" data-action="favorite" data-id="${r.id}" aria-label="${state.favorites.includes(r.id)?'Убрать из избранного':'Сохранить в избранное'}">${icon('heart')}</button></div><div class="swipe-stamp" id="swipe-stamp">НРАВИТСЯ!</div><div class="swipe-content"><div class="eyebrow">${CATEGORIES[r.category]||'ИДЕЯ ДЛЯ УЖИНА'} · ИДЕЯ ПОДАЧИ</div><h2>${esc(r.title)}</h2><div class="swipe-meta"><span>${icon('clock')}${r.time} мин</span><span>${icon('flame')}${nutrition(r)[0]} ккал</span><span>${icon('fork')}${r.ingredients.length} ингредиентов</span></div><div class="swipe-price"><div><strong>≈ ${money(recipeCost(r,state.store))}</strong> <small>/ порция</small></div><span class="swipe-hint">Посмотреть рецепт ${icon('arrow')}</span></div></div></article><div class="swipe-actions"><div><button class="round-action" data-action="undo-skip" aria-label="Вернуть предыдущее блюдо" ${!ui.lastSkip?'disabled':''}>${icon('undo')}</button></div><div><button class="round-action no" data-action="skip" data-id="${r.id}" aria-label="Сейчас не хочу">${icon('x')}</button><div class="action-caption">Не сейчас</div></div><div><button class="round-action yes" data-action="swipe-like" data-id="${r.id}" aria-label="Нравится, сохранить блюдо">${icon('heart')}</button><div class="action-caption">Нравится</div></div><div><button class="round-action cook-action" data-action="swipe-add" data-id="${r.id}" aria-label="Готовить, добавить продукты в корзину">${icon('bag')}</button><div class="action-caption">Готовить</div></div></div><button class="dislike-recipe" data-action="dislike" data-id="${r.id}">${icon('x')}Не люблю это блюдо</button><div class="feed-instruction">${icon('info')}Свайп вправо — нравится. Кнопка «Готовить» — продукты в корзину</div>`:empty('Вы посмотрели всю подборку','Верните пропущенные блюда или измените фильтры. Понравившиеся рецепты сохранены в разделе «Рецепты».','reset-feed','Начать новую подборку','spark')}</div><aside class="feature-aside">${dailyPanel()}${miniCart()}</aside></div><section class="section"><div class="section-head"><div><h2>Ещё немного вдохновения</h2><p>Новые вкусы для привычных дней</p></div><button class="text-button" data-action="nav" data-view="catalog">Все ${RECIPES.length} рецептов ${icon('arrow')}</button></div><div class="recipe-grid home-grid">${cards.map(recipeCard).join('')}</div></section><div class="collection-strip"><button class="collection" data-action="collection" data-kind="quick"><span class="collection-icon">${icon('bolt')}</span><div><h3>Когда совсем нет времени</h3><p>Вкусно за 20 минут</p></div>${icon('arrow')}</button><button class="collection" data-action="collection" data-kind="cheap"><span class="collection-icon">${icon('bag')}</span><div><h3>Приятно для бюджета</h3><p>До 150 ₽ за порцию</p></div>${icon('arrow')}</button><button class="collection" data-action="nav" data-view="favorites"><span class="collection-icon">${icon('heart')}</span><div><h3>Ваша книга вкусов</h3><p>Любимое всегда под рукой</p></div>${icon('arrow')}</button></div>`;
}
function dailyPanel(){const estimate=calorieEstimate(state.profile),kcal=estimate.target;const today=state.selected.filter(x=>x.day===0);const n=today.reduce((a,x)=>a.map((v,i)=>v+nutrition(byId[x.id])[i]),[0,0,0,0]);const progress=Math.min(100,n[0]/kcal*100);return `<section class="daily-panel"><div class="between"><div><div class="eyebrow">ВАШ БАЛАНС НА СЕГОДНЯ</div><h3>${state.profile.goal==='gain'?'Больше энергии':state.profile.goal==='lose'?'Забота о себе':'В своём ритме'}</h3></div><button class="icon-button edit" data-action="nav" data-view="profile" aria-label="Настроить ориентир питания">${icon('edit')}</button></div><div class="nutrition-ring" style="--progress:${progress}"><div class="ring-center"><strong>${n[0].toLocaleString('ru-RU')}</strong><small>из ${kcal.toLocaleString('ru-RU')} ккал</small></div></div><div class="macro-row">${['Белки','Жиры','Углеводы'].map((t,i)=>`<div>${t}<strong>${n[i+1]} <small>г</small></strong><div class="macro-bar"><span style="width:${Math.min(100,n[i+1]/[100,70,250][i]*100)}%"></span></div></div>`).join('')}</div><div class="daily-bottom">${icon('leaf')}${today.length?'Меню на сегодня, на одного человека.':'Выберите первое блюдо — начнём собирать ваш день.'}<br>${estimate.mode==='manual'?'Ваш ориентир из профиля':estimate.personalized?'Расчёт с учётом параметров и цели':'Демоориентир — уточните параметры в профиле'}.</div></section>`;}
function miniCart(){return `<section class="basket-mini"><div class="row"><span class="mini-icon">${icon('bag')}</span><div><h3>Ваша вкусная корзина</h3><p>${state.selected.length?state.selected.length+' '+plural(state.selected.length,'блюдо','блюда','блюд')+' уже выбрано':'Наполнится одним нажатием'}</p></div></div>${state.selected.length?`<div class="mini-items">${state.selected.slice(0,4).map(x=>image(byId[x.id])).join('')}</div><div class="between" style="margin-bottom:16px"><span class="small muted">Продукты в упаковках</span><strong>${money(total())}</strong></div>`:'<p class="mini-empty">Вы выбираете, что приготовить.<br>Мы собираем нужные продукты.</p>'}<button class="primary lime" data-action="nav" data-view="cart">${state.selected.length?'Посмотреть корзину':'Как собирается корзина'} ${icon('arrow')}</button></section>`;}
function plural(n,one,few,many){return n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many;}
function recipeCard(r){const n=nutrition(r);return `<article class="recipe-card" tabindex="0" role="button" data-action="choose" data-id="${r.id}" aria-label="${esc(r.title)}. Открыть рецепт"><div class="recipe-photo">${image(r)}<span class="badge">${icon('clock')}${r.time} мин</span><button class="icon-button ${state.favorites.includes(r.id)?'fav-filled':''}" data-action="favorite" data-id="${r.id}" aria-label="${state.favorites.includes(r.id)?'Убрать из избранного':'В избранное'}">${icon('heart')}</button></div><div class="recipe-info"><h3>${esc(r.title)}</h3><div class="meta">${n[0]} ккал · ${n[1]} г белка · на порцию</div><div class="between"><strong>≈ ${money(recipeCost(r,state.store))} <small>/ порция</small></strong><span class="add-small">${icon(selected(r.id)?'check':'arrow')}</span></div></div></article>`;}
function catalogList(){return recommendations(state,{...ui,excludeSelected:false,excludeSkipped:false,seed:ui.seed}).filter(r=>!ui.recipeFavorites||state.favorites.includes(r.id));}
function catalogResults(){const list=catalogList();return `<div class="between" style="margin-bottom:18px"><span class="catalog-count">${list.length} ${plural(list.length,'рецепт','рецепта','рецептов')} по вашему вкусу</span><span class="small muted">Выберите рецепт — решите, что готовить</span></div>${list.length?`<div class="recipe-grid">${list.slice(0,ui.limit).map(recipeCard).join('')}</div>${list.length>ui.limit?'<button class="secondary load-more" data-action="more">Показать ещё 24</button>':''}`:empty('Пока ничего не нашлось','Попробуйте другой запрос или измените фильтры. Исключённые продукты по-прежнему учитываются.','clear-filters','Сбросить поиск и фильтры','search')}`;}
function recipeTabs(){return `<div class="recipe-subtabs" aria-label="Разделы рецептов"><button data-action="nav" data-view="catalog" class="${ui.view==='catalog'&&!ui.recipeFavorites?'active':''}">${icon('book')}Все рецепты</button><button data-action="nav" data-view="menu" class="${ui.view==='menu'?'active':''}">${icon('calendar')}Моё меню <span>${state.selected.length}</span></button><button data-action="open-recipe-favorites" class="${ui.view==='catalog'&&ui.recipeFavorites?'active':''}">${icon('heart')}Нравится</button></div>`;}
function catalogPage(){return `${recipeTabs()}${title('БОЛЬШАЯ КНИГА ВКУСОВ','На каждый день. И под настроение.',`${RECIPES.length} рецептов и вариаций с ингредиентами, порциями и пошаговым приготовлением.`)}<div class="catalog-tools"><div class="searchbar">${icon('search')}<input id="recipe-search" aria-label="Поиск по блюдам и ингредиентам" placeholder="Блюдо или ингредиент…" value="${esc(ui.search)}" autocomplete="off"></div><button class="secondary" data-action="nav" data-view="profile">${icon('sliders')} Мой вкус</button></div>${filters()}<div id="catalog-results">${catalogResults()}</div>`;}
function empty(head,desc,action,label,ic='bag'){return `<div class="empty">${icon(ic)}<h2>${head}</h2><p>${desc}</p><button class="primary" data-action="${action}">${label} ${icon('arrow')}</button></div>`;}
function favoritesPage(){const list=state.favorites.map(x=>byId[x]).filter(x=>eligible(x,state.profile));return `${title('ВАША ЛИЧНАЯ КОЛЛЕКЦИЯ','Хочется приготовить снова.',`Сохранено ${state.favorites.length} · Под текущие ограничения подходит ${list.length}`)}${list.length?`<div class="recipe-grid">${list.map(recipeCard).join('')}</div>`:empty('Здесь будут ваши любимые блюда','Нажимайте на сердечко в ленте. Избранное сохраняется, а продукты добавляются только при выборе блюда.','to-feed','Найти любимое','heart')}`;}
function mealRow(item,compact=false){const r=byId[item.id];return `<div class="meal-row">${image(r)}<div class="meal-info"><h3><button data-action="details" data-id="${r.id}" style="padding:0;text-align:left">${esc(r.title)}</button></h3>${compact?'':`<p>${r.time} мин · ${nutrition(r)[0]} ккал на порцию · ≈ ${money(recipeCost(r,state.store))}</p>`}<div class="meal-controls"><div class="stepper"><button data-action="portion" data-id="${r.id}" data-delta="-1" aria-label="Уменьшить порции ${esc(r.title)}" ${item.portions===1?'disabled':''}>${icon('minus')}</button><span>${item.portions}</span><button data-action="portion" data-id="${r.id}" data-delta="1" aria-label="Увеличить порции ${esc(r.title)}" ${item.portions===12?'disabled':''}>${icon('plus')}</button></div><span class="small muted">${plural(item.portions,'порция','порции','порций')}</span>${compact?'':`<select class="day-select" data-day-recipe="${r.id}" aria-label="День для блюда ${esc(r.title)}">${Array.from({length:7},(_,n)=>`<option value="${n}" ${item.day===n?'selected':''}>${dayName(n)}</option>`).join('')}</select>`}</div></div><button class="icon-button" data-action="remove" data-id="${r.id}" aria-label="Убрать ${esc(r.title)} из меню">${icon('x')}</button></div>`;}
function menuPage(){const list=state.selected.filter(x=>x.day===ui.day);const macros=list.reduce((acc,x)=>acc.map((v,i)=>v+nutrition(byId[x.id])[i]),[0,0,0,0]);return `${recipeTabs()}${title('ОТ ИДЕИ ДО УЖИНА','Ваше меню, ваши правила.','Выбранные блюда уже связаны с корзиной. Меняйте порции — мы пересчитаем продукты.')}<div class="draft-banner"><div><h3>Меньше «что бы приготовить?»</h3><p>Завтрак, обед и ужин на одного. Нужно больше? Добавьте порцию кнопкой «+» у блюда.</p></div><button class="primary" data-action="plan-day">${icon('spark')}Подобрать день</button></div><div class="tabs">${Array.from({length:7},(_,n)=>`<button class="day-tab ${ui.day===n?'active':''}" data-action="day" data-day="${n}">${dayName(n)}<br><small class="muted">${state.selected.filter(x=>x.day===n).length} ${plural(state.selected.filter(x=>x.day===n).length,'блюдо','блюда','блюд')}</small></button>`).join('')}</div>${list.length?`<div class="between" style="margin-bottom:17px"><span class="small muted">${macros[0]} ккал · Б ${macros[1]} · Ж ${macros[2]} · У ${macros[3]} г · на человека</span><button class="text-button" data-action="nav" data-view="cart">В корзину ${icon('arrow')}</button></div><div class="meal-list">${list.map(x=>mealRow(x)).join('')}</div><button class="secondary load-more" data-action="to-feed">${icon('plus')} Добавить ещё блюдо</button>`:empty('Этот день ещё можно сделать вкуснее','Выберите блюда в ленте или нажмите «Подобрать день». Ингредиенты автоматически появятся в общей корзине.','to-feed','Выбрать блюда','calendar')}`;}
function cartProductRow(i){return `<div class="cart-product ${i.atHome?'at-home':''}"><div class="cart-product-art">${productArt(i,i.id+'cart')}</div><div class="product-info"><h3><button data-action="product-details" data-id="${i.id}">${esc(i.name)}</button></h3><p>${i.amount?`Для рецептов: ${qty(i.amount,i.unit)} · ${i.recipes.length} ${plural(i.recipes.length,'блюдо','блюда','блюд')}`:'Выбрано в каталоге продуктов'}</p><p>${i.packs?`${i.packs} × ${qty(i.pack,i.unit)}${i.amount&&i.leftover>0?' · останется '+qty(i.leftover,i.unit):''}`:'Всё нужное есть дома'}${i.manualPacks?' · вручную '+i.manualPacks+' уп.':''}</p><div class="cart-row-tools">${i.amount?`<button class="home-toggle ${i.homeAvailable?'active':''}" data-action="pantry" data-id="${i.id}">${i.homeAvailable?'✓ Для блюда есть дома':'Для блюда есть дома'}</button>`:''}${i.manualPacks?`<button class="text-button clear-manual" data-action="remove-manual" data-id="${i.id}">Убрать ручной выбор</button>`:''}</div></div><div class="cart-product-right"><strong>${money(i.total)}</strong><small>${money(i.price)} / ${qty(i.pack,i.unit)}</small>${i.packs?`<div class="stepper"><button data-action="product-count" data-id="${i.id}" data-delta="-1" aria-label="Уменьшить количество ${esc(i.name)}">${icon('minus')}</button><span>${i.packs}</span><button data-action="product-count" data-id="${i.id}" data-delta="1" aria-label="Увеличить количество ${esc(i.name)}" ${i.packs>=99?'disabled':''}>${icon('plus')}</button></div>`:'<span class="badge">Есть дома</span>'}</div></div>`;}
function cartPage(){const items=fullBasket();const packs=items.reduce((n,i)=>n+i.packs,0);const consumed=state.selected.reduce((n,x)=>n+recipeCost(byId[x.id],state.store)*x.portions,0);return `${title('ВСЁ НУЖНОЕ В ОДНОМ МЕСТЕ','Ваша корзина.',`${state.store==='fresh'?'FreshMarket':'Авоська'} · ${items.filter(i=>i.packs>0).length} ${plural(items.filter(i=>i.packs>0).length,'товар','товара','товаров')} · ${state.selected.length} ${plural(state.selected.length,'блюдо','блюда','блюд')} в меню`)}<div class="notice">${icon('info')}Продукты из каталога и ингредиенты рецептов в одной корзине. Уже выбранные упаковки засчитываются для блюд. Цены демонстрационные, заказ не отправляется в магазин.</div>${items.length?`<div class="cart-layout"><div>${state.selected.length?`<section class="cart-selected"><div class="between"><h3>Будем готовить</h3><button class="text-button" data-action="nav" data-view="menu">Моё меню ${icon('arrow')}</button></div>${state.selected.map(x=>mealRow(x,true)).join('')}</section>`:''}<section class="panel"><div class="between"><h3>Продукты</h3><button class="text-button" data-action="nav" data-view="home">Добавить ${icon('plus')}</button></div>${items.map((i,idx)=>`${idx===0||i.aisle!==items[idx-1].aisle||i.atHome!==items[idx-1].atHome?`<div class="cart-group">${i.atHome?'Уже есть дома · ':''}${esc(i.aisle)}</div>`:''}${cartProductRow(i)}`).join('')}</section></div><aside class="panel cart-summary"><div class="between"><h3>Ваш заказ</h3><span class="badge">ДЕМО</span></div>${state.selected.length?`<div class="summary-recipes">${state.selected.slice(0,6).map(x=>image(byId[x.id])).join('')}</div>`:''}<div class="store-switch" style="margin-top:18px"><button data-action="store" data-store="fresh" class="${state.store==='fresh'?'active':''}">FreshMarket</button><button data-action="store" data-store="avoska" class="avoska ${state.store==='avoska'?'active':''}">Авоська</button></div><div class="summary-line"><span>Упаковок к покупке</span><strong>${packs}</strong></div>${state.selected.length?`<div class="summary-line"><span>Часть продуктов для блюд*</span><strong>≈ ${money(consumed)}</strong></div><div class="summary-line"><span>Для блюд есть дома</span><strong>${items.filter(i=>i.homeAvailable).length} поз.</strong></div>`:''}<div class="summary-line"><span>Получение</span><strong>${state.fulfillment.mode==='pickup'?'Самовывоз':'Доставка'}</strong></div><div class="summary-total"><span>Продукты</span><strong>${money(total())}</strong></div><p class="small muted" style="margin-top:14px;font-size:10px">${state.selected.length?'*Стоимость использованной части ингредиентов, включая домашние запасы. В корзине покупаются целые упаковки.':'Можно выбрать продукты самостоятельно или добавить сразу все ингредиенты понравившегося блюда.'} Доставка и наличие пока не рассчитываются.</p><button class="primary" data-action="checkout" ${packs?'':'disabled'}>${packs?'Оформить демозаказ':'Все продукты уже есть дома'} ${icon('arrow')}</button><p class="small muted" style="text-align:center;margin-top:11px;font-size:9px">Без оплаты и передачи данных магазину</p>${state.selected.length?`<button class="text-button" style="margin-top:20px" data-action="use-leftovers">${icon('leaf')}Что ещё приготовить из этого?</button>`:`<button class="text-button" style="margin-top:20px" data-action="to-feed">${icon('spark')}Подобрать блюдо</button>`}</aside></div>`:empty('Здесь будет всё для вкусного дня','Выберите продукты в каталоге или нажмите «Готовить» у блюда — добавим его ингредиенты.','to-home','За продуктами','bag')}`;}
const TASTE_SUGGESTIONS=['Курица','Рыба','Грибы','Творог','Сыр','Авокадо','Гречка','Орехи','Лук','Морепродукты'];
function tasteChips(field,value){const terms=tasteTerms(value);return `<div class="taste-chips" data-taste-chips="${field}">${TASTE_SUGGESTIONS.map(term=>`<button type="button" class="taste-chip ${terms.includes(term.toLowerCase())?'active':''}" data-action="taste-term" data-field="${field}" data-term="${term}" aria-pressed="${terms.includes(term.toLowerCase())}">${term}</button>`).join('')}</div>`;}
function syncTasteChips(){for(const field of ['liked','excluded']){const value=$(`[name=${field}]`)?.value||'';const terms=tasteTerms(value);$$(`[data-taste-chips=${field}] button`).forEach(b=>{const active=terms.includes(b.dataset.term.toLowerCase());b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});}}
function calorieCopy(p){const e=calorieEstimate(p);if(e.mode==='manual')return 'Вы задали ориентир вручную. Чтобы он менялся вместе с целью, включите автоматический расчёт.';if(!e.personalized)return `Демоориентир: база 2000 ${e.adjustment>0?'+ 300 для набора':e.adjustment<0?'− 300 для снижения':''} ккал. Укажите пол для расчёта по росту, весу, возрасту и активности.`;if(e.underweight&&p.goal==='lose')return 'При низком весе автоматический дефицит не применяется. Обсудите цель со специалистом.';return `Поддержание ≈ ${e.maintenance.toLocaleString('ru-RU')} ккал${e.adjustment?`, ${e.adjustment>0?'+':'−'} ${Math.abs(e.adjustment)} ккал под цель`:''}.${e.limited?' Достигнута граница автоматического расчёта.':''} Это приблизительный ориентир.`;}
function formCalorieProfile(){const form=$('#profile-form');if(!form)return null;const f=new FormData(form);return {...state.profile,goal:f.get('goal'),sex:f.get('sex'),kcalMode:f.get('kcalMode'),activity:f.get('activity'),height:Number(f.get('height')),weight:Number(f.get('weight')),age:Number(f.get('age')),kcal:Number(f.get('kcal'))};}
function updateCaloriePreview(){const p=formCalorieProfile();if(!p)return;const input=$('[name=kcal]');input.readOnly=p.kcalMode!=='manual';if(input.readOnly)input.value=calorieEstimate(p).target;$('#calorie-note').textContent=calorieCopy(p);}
function integrationPage(){return `${title('FRESHMARKET × АВОСЬКА','От идеи — к реальным заказам.','Что нужно двум сетям, чтобы подключить подбор блюд к действующему приложению.')}<button class="text-button" data-action="nav" data-view="profile">${icon('undo')}Назад в профиль</button><div class="integration-lead"><span class="eyebrow">ПРЕДЛОЖЕНИЕ ДЛЯ ПИЛОТА</span><h2>Выбрали блюдо.<br>Получили готовую корзину магазина.</h2><p>Наш модуль подбирает рецепты и собирает ингредиенты. Покупатель проверяет продукты, а заказ, оплату и доставку завершает в действующем приложении сети.</p><div class="integration-flow"><span>Рецепт</span>${icon('arrow')}<span>Товары сети</span>${icon('arrow')}<span>Корзина</span>${icon('arrow')}<span>Подтверждение заказа</span></div></div><div class="integration-columns"><section class="panel integration-card"><span class="mini-icon">${icon('home')}</span><h3>От магазина</h3><p>Каталог, цены и наличие, механизм заполнения корзины, тестовая среда и контакт разработчика приложения.</p></section><section class="panel integration-card"><span class="mini-icon">${icon('spark')}</span><h3>От нашей команды</h3><p>Подбор по вкусу и цели, рецепты, сопоставление ингредиентов с товарами, расчёт упаковок и интерфейс.</p></section><section class="panel integration-card"><span class="mini-icon">${icon('user')}</span><h3>От покупателя</h3><p>Адрес, выбор блюд, проверка состава и итоговой цены, подтверждение заказа и оплаты.</p></section></div><section class="section"><div class="section-head"><div><h2>Что запросить у FreshMarket и Авоськи</h2><p>Можно передать этот список технической команде сетей.</p></div></div><div class="integration-list"><details open><summary><b>01</b><span>Каталог и доступные товары</span>${icon('chevron')}</summary><div><p>API или согласованная выгрузка с постоянным артикулом каждого товара, названием, фотографией, составом, аллергенами, КБЖУ, размером упаковки и единицей продажи.</p><ul><li>Актуальная цена, скидки и остаток по выбранному магазину или адресу.</li><li>Правила весовых товаров: минимальное количество и шаг покупки.</li><li>Информация о заменах и снятых с продажи позициях.</li></ul><p>Ингредиент «молоко, 200 мл» должен быть связан с конкретным товаром магазина, например упаковкой 1 л. Сначала суммируем потребность всех блюд, затем округляем до упаковок.</p></div></details><details open><summary><b>02</b><span>Добавление в существующую корзину</span>${icon('chevron')}</summary><div><p>Для первого запуска достаточно функции, которая принимает артикулы и количества и возвращает ссылку на заполненную корзину. Ссылка должна открываться в приложении или на сайте выбранной сети.</p><ul><li>Уточнить: новые позиции дополняют корзину или заменяют её.</li><li>Учитывать отсутствие товара, допустимое количество и изменение цены.</li><li>Повтор запроса после сбоя не должен добавлять заказ или продукты дважды.</li><li>Перед подтверждением показать покупателю окончательный состав и сумму.</li></ul><p>Отдельная система оплаты для нашего модуля при таком варианте не требуется: покупатель использует привычное оформление магазина.</p></div></details><details><summary><b>03</b><span>Вход в приложение и профиль покупателя</span>${icon('chevron')}</summary><div><p>Согласовать с разработчиком способ встраивания: экран внутри приложения, WebView или переход по ссылке. Определить, можно ли сохранить вход пользователя и его выбранный адрес.</p><ul><li>Если нужен доступ к личной корзине — согласованный механизм авторизации, например OAuth.</li><li>Только необходимые данные и разрешения; пароли покупателей нам не передаются.</li><li>Секреты интеграции хранятся на сервере, а не в коде браузера.</li><li>Отдельно согласовать правила обработки данных, срок хранения и удаление профиля.</li></ul></div></details><details><summary><b>04</b><span>Доставка, заказ и поддержка</span>${icon('chevron')}</summary><div><p>При переходе в готовую корзину это остаётся на стороне магазина. Если позже захотим оформлять заказ полностью внутри нашего интерфейса, понадобятся дополнительные методы API.</p><ul><li>Зоны, интервалы и стоимость доставки; точки самовывоза.</li><li>Создание заказа, его номер, статусы, отмена и согласование замен.</li><li>Способы оплаты и подтверждение её результата.</li><li>Технический контакт для ошибок и правила обращения покупателя в поддержку.</li></ul><p>Отправленная заявка становится принятым заказом только после подтверждения системы магазина.</p></div></details><details><summary><b>05</b><span>Тестовый доступ и первый пилот</span>${icon('chevron')}</summary><div><p>Начать с одной сети и одного магазина, небольшого списка рецептов и ограниченного набора товаров. Получить тестовые ключи, документацию, лимиты запросов и технический контакт.</p><ul><li>Проверить сценарии: товар закончился, цена изменилась, запрос прервался, покупатель поменял порции.</li><li>Сначала отправлять тестовые заказы без реальной сборки и списания денег.</li><li>После проверки запустить небольшой пилот с подтверждением в приложении магазина.</li><li>Оценить переходы из рецепта в корзину, завершённые заказы, ошибки и обратную связь.</li></ul></div></details></div></section><section class="panel integration-note"><h3>Что уточнить отдельно у двух сетей</h3><p>FreshMarket и Авоське нужно подтвердить, общие ли у них каталог, личный кабинет и система заказов. Если системы разные, подключаем два адаптера: каждый получает свои цены, наличие и корзину. Нынешнее переключение темы в бете ещё не означает техническую интеграцию сетей.</p></section><section class="panel integration-note"><h3>Пример подхода: MCP ВкусВилла</h3><p>ВкусВилл предоставляет поиск товаров, характеристики и создание ссылки на корзину. Это полезный образец для обсуждения. Для нашего первого пилота достаточно обычного API с такими возможностями; MCP можно добавить поверх него.</p><a class="text-button" href="https://mcp.vkusvill.ru/mcp" target="_blank" rel="noopener">Официальное описание MCP ${icon('arrow')}</a></section><p class="integration-status">${icon('info')}Сейчас это демонстрационная версия: цены и ассортимент условные, реальные заказы магазинам не отправляются.</p>`;}

function profilePage(){const p=state.profile;const estimate=calorieEstimate(p);return `${title('У ВКУСА ЕСТЬ ХАРАКТЕР','Расскажите немного о себе.','Так в ленте будет больше того, что подходит именно вам. Всё можно изменить.')}<button class="integration-entry" data-action="nav" data-view="integration"><span class="mini-icon">${icon('home')}</span><span><strong>Интеграция с магазинами</strong><small>Что нужно FreshMarket и Авоське для запуска</small></span>${icon('arrow')}</button><form id="profile-form"><div class="profile-layout"><div><section class="panel profile-section"><h3>С чего начнём?</h3><div class="goal-options">${Object.entries(goals).map(([id,label])=>`<label class="goal-option"><input type="radio" name="goal" value="${id}" ${p.goal===id?'checked':''}>${label}</label>`).join('')}</div></section><section class="panel profile-section"><h3>Ваш ориентир</h3><div class="form-grid"><label class="field">Пол для расчёта<select name="sex"><option value="unspecified" ${p.sex==='unspecified'?'selected':''}>Пока не указан</option><option value="female" ${p.sex==='female'?'selected':''}>Женский</option><option value="male" ${p.sex==='male'?'selected':''}>Мужской</option></select></label><label class="field">Калорийный ориентир<select name="kcalMode"><option value="auto" ${p.kcalMode==='auto'?'selected':''}>Рассчитывать автоматически</option><option value="manual" ${p.kcalMode==='manual'?'selected':''}>Укажу самостоятельно</option></select></label>${[['height','Рост, см',100,230],['weight','Текущий вес, кг',30,250],['target','Желаемый вес, кг',30,250],['age','Возраст, лет',18,100]].map(([name,label,min,max])=>`<label class="field">${label}<input type="number" name="${name}" value="${p[name]}" min="${min}" max="${max}" step="${name==='age'?'1':'0.1'}" required></label>`).join('')}<label class="field">Активность<select name="activity"><option value="low" ${p.activity==='low'?'selected':''}>В основном сижу</option><option value="medium" ${p.activity==='medium'?'selected':''}>Лёгкая активность, 1–2 тренировки</option><option value="high" ${p.activity==='high'?'selected':''}>Регулярные тренировки</option></select></label><label class="field">Ориентир питания, ккал/день<input type="number" name="kcal" value="${estimate.target}" min="1200" max="4500" step="50" ${p.kcalMode==='auto'?'readonly':''} required></label></div><p class="privacy-note"><span id="calorie-note" aria-live="polite">${calorieCopy(p)}</span></p><p class="privacy-note">Расход рассчитывается по текущему весу; желаемый вес — ваш ориентир. Для взрослых 18+. Расчёт не учитывает беременность, лактацию и заболевания. <a href="https://pubmed.ncbi.nlm.nih.gov/2305711/" target="_blank" rel="noopener">О формуле</a>.</p></section><section class="panel profile-section"><h3>Как вам удобно готовить?</h3><div class="form-grid"><label class="field">Время на готовку, мин<input type="number" name="maxTime" value="${p.maxTime}" min="10" max="180" step="5" required></label><label class="field full">Бюджет на порцию, ₽<input type="number" name="budget" value="${p.budget}" min="50" max="1500" step="10" required></label></div><p class="privacy-note">Время и бюджет повышают подходящие блюда в ленте. Для строгого ограничения используйте фильтры каталога.</p></section><section class="panel profile-section"><h3>Ваши вкусы</h3><label class="field">Люблю эти продукты<input name="liked" value="${esc(p.liked)}" placeholder="Например: рыба, авокадо, сыр" maxlength="300"></label>${tasteChips('liked',p.liked)}<label class="field" style="margin-top:22px">Не люблю эти продукты<input name="excluded" value="${esc(p.excluded)}" placeholder="Например: грибы, лук, кинза" maxlength="300"></label>${tasteChips('excluded',p.excluded)}<p class="privacy-note">Можно выбрать подсказки или написать через запятую. Любимое поднимает блюда в подборке, нелюбимое исключает их. Если продукт указан в обоих списках, исключение важнее.</p><div class="taste-learning"><span>${icon('heart')} ${state.favorites.length} в избранном · ${state.disliked.length} не по вкусу</span>${state.disliked.length?'<button type="button" class="text-button" data-action="reset-disliked">Вернуть скрытые блюда</button>':''}</div></section><section class="panel profile-section"><h3>Особенности питания</h3><label class="check-chip" style="margin-bottom:18px;width:max-content"><input type="checkbox" name="vegetarian" ${p.vegetarian?'checked':''}>Без мяса, рыбы и морепродуктов</label><p class="small muted" style="margin-bottom:10px">Исключить рецепты с аллергенами</p><div class="allergen-options">${['молоко','яйца','глютен','рыба','орехи','соя','кунжут','морепродукты'].map(a=>`<label class="check-chip"><input type="checkbox" name="allergens" value="${a}" ${p.allergens.includes(a)?'checked':''}>${a}</label>`).join('')}</div><p class="privacy-note">Сохранение уберёт блюда с исключёнными ингредиентами из меню и корзины. Проверяйте состав конкретного товара на упаковке: производственные следы аллергенов в бете не учтены.</p></section><button class="primary" type="submit">Сохранить мой вкус ${icon('check')}</button><p class="privacy-note">${icon('lock')} Настройки хранятся только в этом браузере. Регистрация не нужна.</p><button class="reset-button" type="button" data-action="reset-dialog" style="margin-top:20px">Удалить мои данные из этого браузера</button></div><aside class="profile-aside">${icon('leaf')}<h3>Ваш ритм.<br>Ваш вкус.</h3><p>Мы будем учитывать вашу цель, любимые блюда и ограничения. И оставим место для новых открытий.</p><div class="value">${state.cooked.length}</div><p>${plural(state.cooked.length,'блюдо приготовлено','блюда приготовлено','блюд приготовлено')} · ваша история вкуса</p><div class="value">${state.favorites.length}</div><p>в избранном</p></aside></div></form>`;}
function openRecipe(id,shouldAdd=true){const r=byId[id];if(!r||!eligible(r,state.profile))return;if(shouldAdd){const added=addRecipe(state,id,ui.view==='menu'?ui.day:0);if(added){persist();render();toast('Ингредиенты добавлены в корзину',()=>{removeRecipe(state,id);persist();closeModal(false);render();toast('Блюдо убрано из корзины');});}}ui.previousFocus=document.activeElement;ui.modal={type:'recipe',id};renderModal();}
function renderModal(){stopCarousel();if(!ui.modal){$('#overlay').innerHTML='';document.body.style.overflow='';return;}document.body.style.overflow='hidden';let content='';const m=ui.modal;
 if(m.type==='product'){content=productModal({id:m.id,...ALL_PRODUCTS[m.id]});}
 else if(m.type==='address'){content=`<section class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close" aria-label="Закрыть">${icon('x')}</button><h2 id="modal-title">${state.fulfillment.mode==='pickup'?'Самовывоз из магазина':'Куда доставить продукты?'}</h2><p>Это пример оформления заказа. Адрес сохраняется только в этом браузере; заказ в магазин не отправляется.</p>${state.fulfillment.mode==='pickup'?`<div class="notice">${state.store==='fresh'?'FreshMarket':'Авоська'} · Благовещенск<br>Список реальных пунктов самовывоза подключим вместе с каталогом магазинов.</div><button class="primary" data-action="close">Продолжить покупки</button>`:`<form id="address-form"><label class="field">Адрес доставки<input name="address" value="${esc(state.fulfillment.address)}" placeholder="Город, улица, дом" maxlength="160" required></label><button class="primary" type="submit" style="width:100%;margin-top:18px">Сохранить адрес</button></form>`}</section>`;}
 else if(m.type==='promo'){content=`<section class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close" aria-label="Закрыть">${icon('x')}</button><div class="eyebrow">БАННЕР СЕТИ</div><h2 id="modal-title">${PROMOS[m.index].title}</h2><p>В бете этот баннер показывает, как наш подбор блюд встраивается в действующее приложение. Условия и актуальность предложения уточняйте у магазина.</p><a class="primary" href="https://www.freshmarket28.ru/" target="_blank" rel="noopener">Перейти на сайт сети ↗</a></section>`;}
 else if(m.type==='recipe'){const r=byId[m.id],item=selected(r.id),portions=item?.portions||1,n=nutrition(r),aa=allergens(r);content=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close" aria-label="Закрыть рецепт">${icon('x')}</button><div class="modal-hero">${image(r,'',false)}<div class="modal-hero-copy"><span class="pill">${icon(item?'check':'book')}${item?'Продукты уже в корзине':'Рецепт из вашей коллекции'}</span><h2 id="modal-title">${esc(r.title)}</h2></div></div><div class="modal-content"><p class="modal-description">${esc(r.description)} · ${r.time} мин</p><div class="between"><span class="small">${item?'Готовим на':'Ингредиенты на'} <strong>${portions} ${plural(portions,'порцию','порции','порций')}</strong></span>${item?`<div class="stepper"><button data-action="portion" data-id="${r.id}" data-delta="-1" aria-label="Меньше порций" ${portions===1?'disabled':''}>${icon('minus')}</button><span>${portions}</span><button data-action="portion" data-id="${r.id}" data-delta="1" aria-label="Больше порций" ${portions===12?'disabled':''}>${icon('plus')}</button></div>`:''}</div><div class="nutrition-pills">${['ккал','белки, г','жиры, г','углеводы, г'].map((v,i)=>`<div class="nutrition-pill"><strong>${n[i]}</strong>${v} / порция</div>`).join('')}</div><div class="recipe-detail-columns"><section><h3>Что понадобится</h3><p class="small muted" style="font-size:10px;margin:7px 0">Отметьте то, что полностью есть дома</p>${r.ingredients.map(i=>`<label class="ingredient-row"><input type="checkbox" data-pantry="${i.id}" ${state.pantry.includes(i.id)?'checked':''}><span>${esc(PRODUCTS[i.id].name)}</span><strong>${qty(i.amount*portions,PRODUCTS[i.id].unit)}</strong></label>`).join('')}<p class="small muted" style="margin-top:15px;font-size:10px">Аллергены: ${aa.length?aa.join(', '):'не отмечены в рецепте'}. Сверьте с упаковкой товара.</p></section><section><h3>Готовим шаг за шагом</h3><ol class="recipe-steps">${r.steps.map((step,i)=>`<li><b>${i+1}</b><span>${esc(step)}</span></li>`).join('')}</ol></section></div><div class="cook-banner"><span>${state.cooked.includes(r.id)?'Уже в вашей истории приготовлений':'Приготовили? Сохраните в историю вкуса.'}</span><button class="text-button" data-action="cooked" data-id="${r.id}">${icon('check')}${state.cooked.includes(r.id)?'Готовили':'Я приготовил(а)'}</button></div><p class="foot-illustration">Фото для вдохновения: подача и состав готового блюда могут отличаться. Рецепт — оригинальный материал для беты; КБЖУ приблизительные, рассчитаны по сырым ингредиентам. Порции и технология требуют редакционной проверки перед коммерческим запуском.</p>${photoCredit(r)}</div><footer class="modal-footer"><div class="cost"><strong>≈ ${money(recipeCost(r,state.store)*portions)}</strong><small>Ингредиенты на ${portions} ${plural(portions,'порцию','порции','порций')} · без округления до упаковок</small></div><button class="primary" data-action="${item?'open-cart':'add-from-modal'}" data-id="${r.id}">${icon('bag')}${item?'Открыть корзину':'Добавить продукты'}</button></footer></section>`;
 } else if(m.type==='checkout'){content=`<section class="modal small-modal success" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close" aria-label="Закрыть">${icon('x')}</button><div class="success-icon">${icon('check')}</div><div class="eyebrow">ДЕМОНСТРАЦИЯ ЗАВЕРШЕНА</div><h2 id="modal-title">Планы на ужин готовы!</h2><p>Демозаказ ${esc(m.order.id)} собран.<br>${m.order.count} ${plural(m.order.count,'позиция','позиции','позиций')} на ${money(m.order.total)}.</p><div class="notice">Это демонстрация. Заказ не отправлен в магазин, деньги не списывались. Рецепты и корзина сохранены.</div><button class="primary" data-action="open-menu">Посмотреть рецепты ${icon('arrow')}</button></section>`;
 } else if(m.type==='about'){content=`<section class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close" aria-label="Закрыть">${icon('x')}</button><div class="eyebrow">FRESHMARKET × АВОСЬКА</div><h2 id="modal-title">Вкусная идея. Рабочая бета.</h2><p>${SHOP_ITEMS.length} продуктов, ${RECIPES.length} рецептов и кулинарных вариаций, подбор по вашим предпочтениям и автоматическая корзина ингредиентов.</p><p>Цены, упаковки и ассортимент демонстрационные. Цена «Авоськи» моделируется для сравнения сценариев и не отражает реальные цены сетей. Реального заказа и оплаты нет.</p><p>Рецепты и справочник пищевой ценности созданы для демонстрации, не прошли кулинарную и диетологическую проверку. Калорийный ориентир рассчитывается приблизительно по параметрам и цели или задаётся вручную; медицинской рекомендацией он не является.</p><p>У каждого рецепта своя фотография из Wikimedia Commons или Unsplash. Фотографии подобраны по типу блюда; результат приготовления может отличаться. Автор и лицензия указаны в рецепте. Для товаров используются условные векторные иллюстрации. Баннеры сети добавлены как примеры карусели действующего приложения. Ваши настройки, вес и выбор сохраняются только в браузере. Их можно удалить в профиле.</p><div class="about-links"><a href="https://www.freshmarket28.ru" target="_blank" rel="noopener">Сайт сети ↗</a><a href="assets/credits.json" target="_blank" rel="noopener">Источники фото ↗</a></div></section>`;
 } else if(m.type==='reset'){content=`<section class="modal small-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close" aria-label="Закрыть">${icon('x')}</button><h2 id="modal-title">Начать с чистого листа?</h2><p>Удалим из этого браузера профиль, избранное, меню, домашние запасы и историю демонстрационных заказов.</p><button class="primary" data-action="confirm-reset">Удалить мои данные</button><button class="secondary" data-action="close" style="margin-left:8px">Отмена</button></section>`;
 } else if(m.type==='leftovers'){const used=new Set(fullBasket().filter(i=>i.leftover>0||i.atHome).map(i=>i.id));const list=recommendations(state,{excludeSkipped:false,seed:ui.seed}).map(r=>({r,overlap:r.ingredients.filter(i=>used.has(i.id)).length})).filter(x=>x.overlap>=2).sort((a,b)=>b.overlap-a.overlap).slice(0,6);content=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close" aria-label="Закрыть">${icon('x')}</button><div class="modal-content"><div class="eyebrow">ПРОДУКТАМ НАЙДЁТСЯ ПРИМЕНЕНИЕ</div><h2 id="modal-title" style="margin:12px 30px 12px 0">Что ещё можно приготовить?</h2><p class="modal-description">Блюда с общими ингредиентами из ваших запасов и остатков упаковок. При выборе проверим нужное количество и пересчитаем покупку.</p>${list.length?`<div class="recipe-grid" style="grid-template-columns:repeat(2,minmax(0,1fr))">${list.map(x=>recipeCard(x.r)).join('')}</div>`:'<p class="small muted">Под текущие ограничения подходящих сочетаний пока нет. Выберите ещё блюдо в каталоге.</p>'}</div></section>`;}
 $('#overlay').innerHTML=`<div class="overlay-backdrop">${content}</div>`;
 setTimeout(()=>$('#overlay .modal-close')?.focus({preventScroll:true}),0);
}
function closeModal(restore=true){ui.modal=null;$('#overlay').innerHTML='';document.body.style.overflow='';if(restore)ui.previousFocus?.focus?.({preventScroll:true});startCarousel();}
function skipRecipe(id){if(!state.skipped.includes(id))state.skipped.push(id);ui.lastSkip=id;persist();render();}
function swipeLike(id){if(!byId[id])return;const previous=[...state.favorites];state.favorites=[...new Set([...state.favorites,id])];state.disliked=state.disliked.filter(x=>x!==id);persist();render();toast('Нравится! Рецепт сохранён, ваш вкус учтён',()=>{state.favorites=previous;persist();render();});}
function swipeAdd(id){const added=addRecipe(state,id);if(added){persist();render();toast('Блюдо выбрано. Все ингредиенты в корзине',()=>{removeRecipe(state,id);persist();render();toast('Выбор отменён');});}}
let suppressClickUntil=0;
function attachSwipe(){const card=$('#swipe-card');if(!card)return;let start=null,delta=0,vertical=false;
 card.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.button!==0)return;start={x:e.clientX,y:e.clientY,id:e.pointerId};delta=0;vertical=false;});
 card.addEventListener('pointermove',e=>{if(!start)return;delta=e.clientX-start.x;const dy=e.clientY-start.y;if(Math.abs(dy)>Math.abs(delta)&&Math.abs(dy)>15){vertical=true;return;}if(vertical||Math.abs(delta)<8)return;card.style.transform=`translateX(${delta*.45}px) rotate(${delta*.035}deg)`;const stamp=$('#swipe-stamp');stamp.style.opacity=Math.min(1,Math.abs(delta)/100);stamp.textContent=delta>0?'НРАВИТСЯ!':'НЕ СЕЙЧАС';});
 const end=e=>{if(!start)return;const id=card.dataset.id;const moved=Math.abs(delta)>15;card.style.transform='';const stamp=$('#swipe-stamp');if(stamp)stamp.style.opacity='0';if(moved||vertical)suppressClickUntil=Date.now()+500;if(!vertical&&Math.abs(delta)>85&&e.type!=='pointercancel'){delta>0?swipeLike(id):skipRecipe(id);}start=null;};
 card.addEventListener('pointerup',end);card.addEventListener('pointercancel',end);card.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse')end(e);});
}
function productQuantity(id){return fullBasket().find(i=>i.id===id)?.packs||0;}
function productCard(p,compact=false){const count=productQuantity(p.id),price=productPrice(p,state.store);return `<article class="shop-card ${compact?'compact':''}" data-product-card="${p.id}"><button class="shop-photo" data-action="product-details" data-id="${p.id}" aria-label="Подробнее: ${esc(p.name)}">${productArt(p,p.id+(compact?'c':'g'))}</button><button class="product-heart ${state.productFavorites.includes(p.id)?'is-saved fav-filled':''}" data-action="product-favorite" data-id="${p.id}" aria-label="${state.productFavorites.includes(p.id)?'Убрать товар из избранного':'Сохранить товар'}">${icon('heart')}</button><div class="shop-card-info"><div class="shop-price">${money(price)}</div><button class="shop-product-name" data-action="product-details" data-id="${p.id}">${esc(p.name)}</button><div class="shop-pack">${qty(p.pack,p.unit)} · ${state.store==='fresh'?'FreshMarket':'Авоська'}</div>${count?`<div class="shop-stepper"><button data-action="product-count" data-id="${p.id}" data-delta="-1" aria-label="Уменьшить количество ${esc(p.name)}">${icon('minus')}</button><span>${count} ${plural(count,'упаковка','упаковки','упаковок')}</span><button data-action="product-count" data-id="${p.id}" data-delta="1" aria-label="Увеличить количество ${esc(p.name)}" ${count>=99?'disabled':''}>${icon('plus')}</button></div>`:`<button class="product-add" data-action="product-count" data-id="${p.id}" data-delta="1">В корзину ${icon('plus')}</button>`}</div></article>`;}
const PROMOS=[{image:'promo-bonus',title:'Дарим бонусы круглый год'},{image:'promo-game',title:'Игра начинается — акция сети'},{image:'promo-price',title:'Топ-цена — предложение сети'},{image:'promo-gifts',title:'Подарочные карты'},{recipe:true,title:'Выберите блюдо — мы соберём продукты'}];
function bannerContent(){return `<div class="promo-track" style="transform:translateX(-${ui.banner*100}%)">${PROMOS.map((p,i)=>p.recipe?`<button class="promo-slide recipe-promo" data-action="to-feed" tabindex="${ui.banner===i?'0':'-1'}" aria-hidden="${ui.banner!==i}"><div><span class="promo-eyebrow">НОВОЕ В ПРИЛОЖЕНИИ</span><h2>Не знаете,<br>что приготовить?</h2><p>Сохраните любимое одним свайпом.<br>Готовьте, когда захотите.</p><span class="promo-cta">Попробовать ${icon('arrow')}</span></div><img src="assets/bowl.jpg" alt="Боул с лососем и авокадо"></button>`:`<button class="promo-slide" data-action="promo-info" data-slide="${i}" tabindex="${ui.banner===i?'0':'-1'}" aria-label="${p.title}" aria-hidden="${ui.banner!==i}"><img src="assets/${p.image}.jpg" alt="${p.title}" draggable="false"></button>`).join('')}</div>`;}
function carousel(){return `<section class="promo-carousel" aria-label="Баннеры магазина" aria-roledescription="карусель"><div class="promo-window" id="promo-window">${bannerContent()}</div><div class="promo-controls"><button class="promo-arrow" data-action="banner-prev" aria-label="Предыдущий баннер">${icon('chevron')}</button><div class="promo-dots">${PROMOS.map((p,i)=>`<button data-action="banner-dot" data-index="${i}" class="${ui.banner===i?'active':''}" aria-label="Баннер ${i+1}: ${p.title}" aria-current="${ui.banner===i?'true':'false'}"></button>`).join('')}</div><button class="promo-arrow" data-action="banner-next" aria-label="Следующий баннер">${icon('chevron')}</button><button class="promo-pause" data-action="banner-pause" aria-label="${ui.bannerPaused?'Включить':'Остановить'} автоматическое перелистывание">${ui.bannerPaused?'▶':'Ⅱ'}</button></div></section>`;}
function homeResults(){const list=shopFilter(state,ui.shop);return `<div class="section-head shop-results-head"><div><h2>${ui.shop.favorites?'Избранные продукты':SHOP_CATEGORIES.find(c=>c[0]===ui.shop.category)?.[1]||'Все продукты'}</h2><p>${list.length} ${plural(list.length,'товар','товара','товаров')} · демонстрационный ассортимент</p></div><label class="shop-sort">Сначала<select id="shop-sort" aria-label="Сортировка товаров"><option value="recommended" ${ui.shop.sort==='recommended'?'selected':''}>Рекомендуемые</option><option value="price-up" ${ui.shop.sort==='price-up'?'selected':''}>Недорогие</option><option value="price-down" ${ui.shop.sort==='price-down'?'selected':''}>Дорогие</option><option value="name" ${ui.shop.sort==='name'?'selected':''}>По алфавиту</option></select></label></div>${list.length?`<div class="shop-grid">${list.slice(0,ui.shopLimit).map(p=>productCard(p)).join('')}</div>${list.length>ui.shopLimit?`<button class="secondary load-more" data-action="more-products">Показать ещё ${Math.min(30,list.length-ui.shopLimit)} из ${list.length-ui.shopLimit}</button>`:''}`:empty('Таких товаров пока нет','Измените запрос или фильтры. В каталоге есть продукты для завтрака, обеда, ужина и просто к чаю.','reset-shop','Показать весь каталог','search')}`;}
function homePage(){const hasFilter=ui.shop.search||ui.shop.category!=='all'||ui.shop.favorites||ui.shop.personal;return `<section class="shop-top"><div class="delivery-address"><span>${state.fulfillment.mode==='pickup'?'Пункт самовывоза':'Адрес доставки'}</span><button data-action="delivery-address">${icon('pin')}<strong>${state.fulfillment.mode==='pickup'?(state.store==='fresh'?'FreshMarket':'Авоська')+' · выбрать магазин':esc(state.fulfillment.address||'Благовещенск · укажите адрес')}</strong>${icon('chevron')}</button></div><div class="fulfillment-switch"><button class="${state.fulfillment.mode==='delivery'?'active':''}" data-action="fulfillment" data-mode="delivery">Доставка</button><button class="${state.fulfillment.mode==='pickup'?'active':''}" data-action="fulfillment" data-mode="pickup">Самовывоз</button></div></section><div class="shop-search">${icon('search')}<input id="shop-search" value="${esc(ui.shop.search)}" placeholder="Быстрый поиск товаров" aria-label="Поиск продуктов" autocomplete="off">${ui.shop.search?'<button data-action="clear-shop-search" aria-label="Очистить поиск">'+icon('x')+'</button>':'<span>'+SHOP_ITEMS.length+' товаров</span>'}</div><div id="home-discovery" ${hasFilter?'hidden':''}>${carousel()}<section class="daily-products"><div class="section-head"><div><h2>На каждый день</h2><p>Самое нужное — всегда под рукой</p></div><button class="text-button" data-action="all-products">Все продукты ${icon('arrow')}</button></div><div class="products-rail">${SHOP_ITEMS.slice(0,10).map(p=>productCard(p,true)).join('')}</div></section><button class="smart-feature" data-action="to-feed"><span class="smart-feature-icon">${icon('spark')}</span><div><span class="eyebrow">НОВАЯ ВОЗМОЖНОСТЬ</span><h3>Покупайте под блюдо, а не наоборот</h3><p>${RECIPES.length} рецептов · ваши вкусы · продукты к блюдам</p></div><span class="smart-feature-arrow">${icon('arrow')}</span></button></div><section class="products-catalog" id="products-catalog"><div class="shop-categories">${SHOP_CATEGORIES.map(([key,label,ic])=>`<button data-action="shop-category" data-category="${key}" class="shop-category ${ui.shop.category===key?'active':''}">${icon(ic)}${label}</button>`).join('')}</div><div class="shop-filters"><button class="chip ${ui.shop.favorites?'active':''}" data-action="shop-favorites">${icon('heart')}Избранное</button><button class="chip ${ui.shop.personal?'active':''}" data-action="shop-personal">${icon('sliders')}Мои ограничения</button><span>Цены и ассортимент — демо</span></div><div id="shop-results">${homeResults()}</div></section><p class="shop-disclaimer">Условные иллюстрации товаров. Баннеры сети показывают оформление приложения; условия предложений проверяйте в действующем приложении магазина.</p>`;}
function updateShopResults(){if(!$('#shop-results'))return;$('#shop-results').innerHTML=homeResults();const discovery=$('#home-discovery');if(discovery)discovery.hidden=!!(ui.shop.search||ui.shop.category!=='all'||ui.shop.favorites||ui.shop.personal);startCarousel();}
let bannerTimer=null,bannerHover=false;
function setBanner(index){ui.banner=(index+PROMOS.length)%PROMOS.length;const track=$('.promo-track');if(!track)return;track.style.transform=`translateX(-${ui.banner*100}%)`;$$('.promo-slide').forEach((s,i)=>{s.tabIndex=i===ui.banner?0:-1;s.setAttribute('aria-hidden',String(i!==ui.banner));});$$('.promo-dots button').forEach((b,i)=>{b.classList.toggle('active',i===ui.banner);b.setAttribute('aria-current',String(i===ui.banner));});}
function stopCarousel(){if(bannerTimer)clearInterval(bannerTimer);bannerTimer=null;}
function startCarousel(){stopCarousel();if(ui.view!=='home'||ui.bannerPaused||ui.modal||bannerHover||document.hidden||$('#home-discovery')?.hidden||!$('#promo-window'))return;bannerTimer=setInterval(()=>setBanner(ui.banner+1),5000);}
function attachCarousel(){const win=$('#promo-window');if(!win)return;let start=null;
 win.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY};});
 win.addEventListener('pointerup',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)){suppressClickUntil=Date.now()+600;setBanner(ui.banner+(dx<0?1:-1));startCarousel();}start=null;});
 win.addEventListener('pointercancel',()=>{start=null;});
 const wrap=$('.promo-carousel');wrap.addEventListener('mouseenter',()=>{bannerHover=true;stopCarousel();});wrap.addEventListener('mouseleave',()=>{bannerHover=false;startCarousel();});wrap.addEventListener('focusin',()=>stopCarousel());wrap.addEventListener('focusout',()=>startCarousel());
}
function productModal(p){const r=fullBasket().find(i=>i.id===p.id),count=r?.packs||0;return `<section class="modal small-modal product-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="icon-button modal-close" data-action="close" aria-label="Закрыть товар">${icon('x')}</button><div class="product-modal-art">${productArt(p,p.id+'modal')}</div><div class="eyebrow">${state.store==='fresh'?'FRESHMARKET':'АВОСЬКА'} · ДЕМОТОВАР</div><h2 id="modal-title">${esc(p.name)}</h2><p>${qty(p.pack,p.unit)} · ${esc(p.aisle)}</p><div class="product-modal-price">${money(productPrice(p,state.store))}</div><p>Аллергены: ${(p.allergens||[]).length?p.allergens.join(', '):'не указаны в демокаталоге'}. Состав и следы аллергенов проверяйте на упаковке.</p>${r?.recipePacks?`<div class="notice">Для выбранных блюд нужно не меньше ${r.recipePacks} ${plural(r.recipePacks,'упаковки','упаковок','упаковок')}. Уже выбранные вами упаковки засчитываются для рецептов.</div>`:''}<div class="shop-stepper modal-quantity"><button data-action="product-count" data-id="${p.id}" data-delta="-1" aria-label="Уменьшить количество" ${!count?'disabled':''}>${icon('minus')}</button><span>${count?count+' '+plural(count,'упаковка','упаковки','упаковок'):'Добавить в корзину'}</span><button data-action="product-count" data-id="${p.id}" data-delta="1" aria-label="Добавить упаковку" ${count>=99?'disabled':''}>${icon('plus')}</button></div><button class="primary" style="width:100%;margin-top:14px" data-action="open-cart">Открыть корзину ${icon('arrow')}</button>${Object.hasOwn(PRODUCTS,p.id)?`<button class="text-button" style="margin-top:20px" data-action="recipes-with-product" data-id="${p.id}">${icon('fork')}Что приготовить из этого?</button>`:''}<p class="foot-illustration">Иллюстрация условная. Цена и фасовка примерные, наличие не подключено.</p></section>`;}

document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action]');if(!b){if(e.target.classList.contains('overlay-backdrop'))closeModal();return;}const a=b.dataset.action,id=b.dataset.id;
 if(['choose','promo-info','to-feed'].includes(a)&&Date.now()<suppressClickUntil)return;
 switch(a){
 case 'open-recipe-favorites':go('favorites');break;
 case 'recipe-favorites':ui.recipeFavorites=!ui.recipeFavorites;ui.limit=24;render();break;
 case 'shop-category':ui.shop.category=b.dataset.category;ui.shopLimit=30;render();$('#products-catalog')?.scrollIntoView?.({block:'start',behavior:'smooth'});break;
 case 'shop-favorites':ui.shop.favorites=!ui.shop.favorites;ui.shopLimit=30;render();break;
 case 'shop-personal':ui.shop.personal=!ui.shop.personal;ui.shopLimit=30;render();break;
 case 'reset-shop':ui.shop={category:'all',search:'',sort:'recommended',favorites:false,personal:false};ui.shopLimit=30;render();break;
 case 'clear-shop-search':ui.shop.search='';ui.shopLimit=30;render();$('#shop-search')?.focus();break;
 case 'more-products':ui.shopLimit+=30;updateShopResults();break;
 case 'all-products':$('#products-catalog')?.scrollIntoView?.({block:'start',behavior:'smooth'});break;
 case 'product-details':ui.previousFocus=document.activeElement;ui.modal={type:'product',id};renderModal();break;
 case 'product-favorite':state.productFavorites=state.productFavorites.includes(id)?state.productFavorites.filter(x=>x!==id):[...state.productFavorites,id];persist();render();break;
 case 'product-count':{const row=fullBasket().find(i=>i.id===id);const current=row?.packs||0;const needed=row?.recipePacks||0;const delta=Number(b.dataset.delta);if(delta<0&&current<=needed){toast('Эти упаковки нужны для блюд. Измените порции или отметьте продукт как имеющийся дома.');break;}setProductCount(state,id,current+delta);persist();render();if(ui.modal)renderModal();if(current===0&&delta>0)toast('Товар добавлен в корзину');break;}
 case 'remove-manual':setProductCount(state,id,0);persist();render();toast('Ручной выбор отменён. Потребность рецептов сохранена.');break;
 case 'recipes-with-product':{const name=ALL_PRODUCTS[id].name;closeModal(false);go('catalog');ui.search=name;ui.recipeFavorites=false;render();break;}
 case 'fulfillment':state.fulfillment.mode=b.dataset.mode;persist();render();break;
 case 'delivery-address':ui.previousFocus=document.activeElement;ui.modal={type:'address'};renderModal();break;
 case 'banner-prev':setBanner(ui.banner-1);startCarousel();break;
 case 'banner-next':setBanner(ui.banner+1);startCarousel();break;
 case 'banner-dot':setBanner(Number(b.dataset.index));startCarousel();break;
 case 'banner-pause':ui.bannerPaused=!ui.bannerPaused;render();break;
 case 'promo-info':ui.previousFocus=document.activeElement;ui.modal={type:'promo',index:Number(b.dataset.slide)};renderModal();break;
 case 'nav':go(b.dataset.view);break;
 case 'to-home':go('home');break;
 case 'to-feed':go('feed');break;
 case 'category':ui.category=b.dataset.category;ui.limit=24;render();break;
 case 'quick':ui.quick=!ui.quick;ui.limit=24;render();break;
 case 'cheap':ui.cheap=!ui.cheap;ui.limit=24;render();break;
 case 'more':ui.limit+=24;$('#catalog-results').innerHTML=catalogResults();break;
 case 'clear-filters':ui.category='all';ui.quick=false;ui.cheap=false;ui.search='';render();break;
 case 'collection':ui.category='all';ui.quick=b.dataset.kind==='quick';ui.cheap=b.dataset.kind==='cheap';go('catalog');break;
 case 'choose':openRecipe(id,false);break;
 case 'details':openRecipe(id,false);break;
 case 'favorite':{const was=state.favorites.includes(id);state.favorites=was?state.favorites.filter(x=>x!==id):[...state.favorites,id];if(!was)state.disliked=state.disliked.filter(x=>x!==id);persist();render();if(ui.modal)renderModal();toast(was?'Убрано из избранного':'Сохранено в избранном. Ваш вкус учтён');break;}
 case 'dislike':{if(!byId[id])break;const old=[...state.disliked],oldFav=[...state.favorites];state.disliked=[...new Set([...state.disliked,id])];state.favorites=state.favorites.filter(x=>x!==id);persist();render();toast('Блюдо скрыто. Похожие будем предлагать реже',()=>{state.disliked=old;state.favorites=oldFav;persist();render();});break;}
 case 'reset-disliked':{state.disliked=[];persist();b.closest('.taste-learning').innerHTML='<span>Скрытые блюда возвращены в подборку</span>';toast('Блюда возвращены. Исключения продуктов сохранены');break;}
 case 'taste-term':{const field=b.dataset.field,other=field==='liked'?'excluded':'liked';const input=$(`[name=${field}]`),opposite=$(`[name=${other}]`);const term=b.dataset.term.toLowerCase(),terms=tasteTerms(input.value),active=terms.includes(term);input.value=(active?terms.filter(t=>t!==term):[...terms,term]).join(', ');if(!active)opposite.value=tasteTerms(opposite.value).filter(t=>t!==term).join(', ');syncTasteChips();break;}
 case 'skip':skipRecipe(id);break;
 case 'swipe-like':swipeLike(id);break;
 case 'swipe-add':swipeAdd(id);break;
 case 'undo-skip':if(ui.lastSkip){state.skipped=state.skipped.filter(x=>x!==ui.lastSkip);ui.lastSkip=null;persist();render();toast('Предыдущее блюдо возвращено в подборку');}break;
 case 'reset-feed':state.skipped=[];ui.category='all';ui.quick=false;ui.cheap=false;ui.lastSkip=null;persist();render();break;
 case 'portion':{const item=selected(id);if(item){item.portions=Math.max(1,Math.min(12,item.portions+Number(b.dataset.delta)));persist();render();if(ui.modal)renderModal();}break;}
 case 'remove':{const old=selected(id);removeRecipe(state,id);persist();render();toast('Блюдо и ненужные ингредиенты убраны',()=>{if(!selected(id))state.selected.push(old);persist();render();});break;}
 case 'pantry':state.pantry=state.pantry.includes(id)?state.pantry.filter(x=>x!==id):[...state.pantry,id];persist();render();break;
 case 'store':state.store=b.dataset.store;persist();render();toast(`Выбрана ${state.store==='fresh'?'сеть FreshMarket':'сеть «Авоська»'}. Демоценовая модель пересчитана`);break;
 case 'switch-store':state.store=state.store==='fresh'?'avoska':'fresh';persist();render();toast(`Магазин: ${state.store==='fresh'?'FreshMarket':'Авоська'} · цены демонстрационные`);break;
 case 'day':ui.day=Number(b.dataset.day);render();break;
 case 'plan-day':{const previous=state.selected.map(x=>({...x}));const result=planDay(state,ui.day,ui.seed);persist();render();toast(result.added?`Добавлено ${result.added} ${plural(result.added,'блюдо','блюда','блюд')} по одной порции. Продукты в корзине`:'Меню уже подобрано либо нет подходящих блюд',result.added?()=>{state.selected=previous;persist();render();}:null);break;}
 case 'close':closeModal();break;
 case 'open-cart':go('cart');break;
 case 'open-menu':go('menu');break;
 case 'add-from-modal':if(addRecipe(state,id)){persist();render();renderModal();toast('Ингредиенты добавлены');}break;
 case 'about':ui.previousFocus=document.activeElement;ui.modal={type:'about'};renderModal();break;
 case 'cooked':{if(!state.cooked.includes(id)){state.cooked.push(id);persist();renderModal();toast('Сохранено в истории приготовлений');}else toast('Это блюдо уже в истории');break;}
 case 'checkout':{if(!fullBasket().some(i=>i.packs>0))return;const order={id:'FM-'+Date.now().toString().slice(-6),total:total(),count:fullBasket().filter(i=>!i.atHome).length,date:new Date().toISOString()};state.history=[order,...state.history].slice(0,20);persist();ui.previousFocus=document.activeElement;ui.modal={type:'checkout',order};renderModal();break;}
 case 'use-leftovers':ui.previousFocus=document.activeElement;ui.modal={type:'leftovers'};renderModal();break;
 case 'reset-dialog':ui.previousFocus=document.activeElement;ui.modal={type:'reset'};renderModal();break;
 case 'confirm-reset':state=defaults();try{localStorage.removeItem(STORE_KEY);}catch{}closeModal(false);ui.category='all';ui.quick=false;ui.cheap=false;ui.shop={category:'all',search:'',sort:'recommended',favorites:false,personal:false};ui.shopLimit=30;ui.recipeFavorites=false;ui.day=0;go('home');toast('Ваши данные удалены из браузера');break;
 case 'toast-action':{const f=ui.toastAction;ui.toastAction=null;$('#toast').classList.remove('visible');if(f)f();break;}
 }
});
document.addEventListener('input',e=>{if(['height','weight','age','kcal'].includes(e.target.name))updateCaloriePreview();if(['liked','excluded'].includes(e.target.name))syncTasteChips();if(e.target.id==='shop-search'){ui.shop.search=e.target.value;ui.shopLimit=30;updateShopResults();}if(e.target.id==='recipe-search'){ui.search=e.target.value;ui.limit=24;$('#catalog-results').innerHTML=catalogResults();}});
document.addEventListener('change',e=>{const t=e.target;if(['goal','sex','activity','kcalMode'].includes(t.name))updateCaloriePreview();if(t.id==='shop-sort'){ui.shop.sort=t.value;updateShopResults();}if(t.dataset.pantry){const id=t.dataset.pantry;state.pantry=t.checked?[...new Set([...state.pantry,id])]:state.pantry.filter(x=>x!==id);persist();render();renderModal();}if(t.dataset.dayRecipe){const item=selected(t.dataset.dayRecipe);if(item){item.day=Number(t.value);persist();render();toast('Блюдо перенесено. Корзина сохранена');}}});
document.addEventListener('submit',e=>{if(e.target.id==='address-form'){e.preventDefault();state.fulfillment.address=String(new FormData(e.target).get('address')||'').trim().slice(0,160);persist();closeModal(false);render();toast('Адрес сохранён для демонстрации');return;}if(e.target.id!=='profile-form')return;e.preventDefault();const form=e.target;if(!form.reportValidity())return;const f=new FormData(form);const p={...state.profile};for(const key of ['height','weight','target','age','kcal','maxTime','budget'])p[key]=Number(f.get(key));p.goal=f.get('goal');p.activity=f.get('activity');p.sex=f.get('sex');p.kcalMode=f.get('kcalMode');p.kcal=calorieEstimate(p).target;p.vegetarian=f.has('vegetarian');p.allergens=f.getAll('allergens');p.excluded=String(f.get('excluded')||'').trim();p.liked=String(f.get('liked')||'').trim();p.configured=true;const before=state.selected.length;state.profile=p;state.selected=state.selected.filter(x=>eligible(byId[x.id],p));state.skipped=[];persist();ui.category='all';ui.quick=false;ui.cheap=false;go('feed');toast(before>state.selected.length?`Вкус сохранён. Исключено несовместимых блюд: ${before-state.selected.length}`:'Ваш вкус сохранён. Подборка обновилась');});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&ui.modal){closeModal();return;}if(ui.modal&&e.key==='Tab'){const focusable=$$('#overlay button:not(:disabled),#overlay input,#overlay a,#overlay select').filter(x=>x.offsetParent!==null);if(!focusable.length)return;const first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('article[data-action]')){e.preventDefault();openRecipe(e.target.dataset.id,false);}if(!ui.modal&&e.target.id==='swipe-card'&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();e.key==='ArrowRight'?swipeLike(e.target.dataset.id):skipRecipe(e.target.dataset.id);$('#swipe-card')?.focus({preventScroll:true});}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1)||'home';go(['home','feed','catalog','menu','cart','favorites','profile','integration'].includes(v)?v:'home',{replace:true});});
document.addEventListener('visibilitychange',()=>document.hidden?stopCarousel():startCarousel());
render();if(storageAvailable)persist();if(!storageAvailable)toast('Бета работает, но сохранение в браузере недоступно');else if(storageRecovered)toast('Повреждённые данные восстановлены. Можно начать с чистого листа.');
